css:
:root { color-scheme: dark; }

body, .min-h-screen, header, aside, main, .flex-1,
[class*="bg-white"], [class*="bg-neutral-0"], [class*="bg-neutral-1"], [class*="bg-black"] {
  background-color: #0f1115 !important;
}

header, aside, .versions, [class*="bg-white"] { background-color: #171a21 !important; }

body, p, span, div, li, td, th, dt, dd, label, h1, h2, h3, h4, h5, h6,
nav a, aside a, main a, .text-h3, .text-b1, .text-b2, .text-b3, .text-b4, .text-h4 {
  color: #e6e8ec !important;
}

a, a:visited { color: #7cb8ff !important; }
nav a:hover, aside a:hover, main a:hover { color: #b3d7ff !important; }

[class*="border-"], table, th, td, hr, li, ol, ul { border-color: #2c313b !important; }

table, th, td { background-color: transparent !important; }
th { background-color: #1c2029 !important; }

input, textarea, select, #query {
  background-color: #1c2029 !important;
  color: #e6e8ec !important;
  border-color: #2c313b !important;
}
input::placeholder, textarea::placeholder { color: #8a909c !important; }

pre, code, [class*="bg-neutral-1"] {
  background-color: #1c2029 !important;
  color: #e6e8ec !important;
}


/* Version and requirement badges keep their light backgrounds otherwise. */
[class*="bg-neutral-200"] { background-color: #262b35 !important; }
[class*="bg-green-200"] { background-color: #1d3b2a !important; }
